('019e7529-c948-72a9-a3d1-ab645dc2fd8d', 'Flujo SAC (Advanced React Flow)', 'Flujo generado para el editor avanzado.', 1, '{"nodes":[{"id":"n1_trig","type":"trigger","position":{"x":100,"y":100},"data":{"label":"Disparador: Menú Principal","isValid":true,"output":[{"reply_type_text":"On exact match","reply_type":"1","rel_type":"customer","trigger":"quiero mas informacion"}]}},{"id":"n1_text","type":"textMessage","position":{"x":500,"y":100},"data":{"label":"Enviar Menú","isValid":true,"output":[{"reply_text":"¡Hola {contact.name}! ¿En qué puedo ayudarte hoy?\n\n*1.* 📦 Productos y Servicios\n*2.* 📅 Agendar \/ Gestionar Cita\n*3.* 👤 Hablar con un Asesor Comercial"}]}},{"id":"n2_trig","type":"trigger","position":{"x":900,"y":-100},"data":{"label":"Disparador: Opción 1","isValid":true,"output":[{"reply_type_text":"On exact match","reply_type":"1","rel_type":"customer","trigger":"1,productos,servicios,paquetes"}]}},{"id":"n2_text","type":"textMessage","position":{"x":1300,"y":-100},"data":{"label":"Preguntar Sector","isValid":true,"output":[{"reply_text":"¡Excelente! Para darte la información correcta, cuéntame: ¿A qué sector pertenece tu empresa?\n\n*1.* 🚗 Talleres Automotrices\n*2.* 🏥 Clínicas y Consultorios..."}]}},{"id":"n3_trig","type":"trigger","position":{"x":1700,"y":-100},"data":{"label":"Disparador: Sector 1-9","isValid":true,"output":[{"reply_type_text":"On exact match","reply_type":"1","rel_type":"customer","trigger":"1,2,3,4,5,6,7,8,9"}]}},{"id":"n3_text","type":"textMessage","position":{"x":2100,"y":-100},"data":{"label":"Preguntar Problema","isValid":true,"output":[{"reply_text":"Entendido. ¿Cuál es el desafío principal que enfrentas en tu negocio hoy?\n\n*1.* ⏳ Me demoro en responder y pierdo clientes..."}]}},{"id":"n4_trig","type":"trigger","position":{"x":900,"y":300},"data":{"label":"Disparador: Opción 2","isValid":true,"output":[{"reply_type_text":"On exact match","reply_type":"1","rel_type":"customer","trigger":"2,agendar"}]}},{"id":"n4_text","type":"textMessage","position":{"x":1300,"y":300},"data":{"label":"Enviar Horarios","isValid":true,"output":[{"reply_text":"Te enviaré el enlace para que elijas el horario de tu cita."}]}},{"id":"n5_trig","type":"trigger","position":{"x":900,"y":500},"data":{"label":"Disparador: Opción 3","isValid":true,"output":[{"reply_type_text":"On exact match","reply_type":"1","rel_type":"customer","trigger":"3,asesor"}]}},{"id":"n5_text","type":"textMessage","position":{"x":1300,"y":500},"data":{"label":"Asignar Asesor","isValid":true,"output":[{"reply_text":"En unos momentos un asesor comercial se comunicará contigo. Por favor, mantente en línea..."}]}}],"edges":[{"id":"e_n1_trig_n1_text","source":"n1_trig","target":"n1_text","animated":true,"style":{"strokeWidth":2}},{"id":"e_n1_text_n2_trig","source":"n1_text","target":"n2_trig","animated":true,"style":{"strokeWidth":2}},{"id":"e_n2_trig_n2_text","source":"n2_trig","target":"n2_text","animated":true,"style":{"strokeWidth":2}},{"id":"e_n2_text_n3_trig","source":"n2_text","target":"n3_trig","animated":true,"style":{"strokeWidth":2}},{"id":"e_n3_trig_n3_text","source":"n3_trig","target":"n3_text","animated":true,"style":{"strokeWidth":2}},{"id":"e_n1_text_n4_trig","source":"n1_text","target":"n4_trig","animated":true,"style":{"strokeWidth":2}},{"id":"e_n4_trig_n4_text","source":"n4_trig","target":"n4_text","animated":true,"style":{"strokeWidth":2}},{"id":"e_n1_text_n5_trig","source":"n1_text","target":"n5_trig","animated":true,"style":{"strokeWidth":2}},{"id":"e_n5_trig_n5_text","source":"n5_trig","target":"n5_text","animated":true,"style":{"strokeWidth":2}}]}', NOW(), NOW());
